// Solve solves an alphametics puzzle of the form
// "WORD + WORD + ... == WORD" and returns a mapping from each letter
// to a distinct digit.
func Solve(puzzle string) (map[string]int, error) {
	eqParts := strings.Split(puzzle, "==")
	if len(eqParts) != 2 {
		return nil, errors.New("invalid puzzle: expected exactly one '=='")
	}
	addendStr := strings.TrimSpace(eqParts[0])
	resultStr := strings.TrimSpace(eqParts[1])

	words := strings.Fields(addendStr)
	// replace '+' separators: Fields splits on any whitespace, and '+' is a standalone token
	var addends []string
	for _, f := range words {
		if f == "+" {
			continue
		}
		if !isWord(f) {
			return nil, fmt.Errorf("invalid puzzle: %q is not a word", f)
		}
		addends = append(addends, f)
	}
	results := strings.Fields(resultStr)
	if len(results) != 1 || !isWord(results[0]) {
		return nil, errors.New("invalid puzzle: expected exactly one result word")
	}
	if len(addends) == 0 {
		return nil, errors.New("invalid puzzle: no addends")
	}
	all := append(addends, results[0])

	// coefficient of each letter in the equation sum(addends) - result = 0
	coeff := make(map[string]int)
	leading := make(map[string]bool)
	for i, w := range all {
		sign := 1
