// Solve finds an assignment of distinct digits to the letters of an
// alphametics puzzle of the form "WORD + WORD + ... == WORD".
// It returns the mapping from each letter to its digit, or an error
// if the puzzle is malformed or has no solution.
func Solve(puzzle string) (map[string]int, error) {
	eqParts := strings.Split(puzzle, "==")
	if len(eqParts) != 2 {
		return nil, errors.New("invalid puzzle: expected exactly one '=='")
	}

	addends, err := parseSide(eqParts[0])
	if err != nil {
		return nil, err
	}
	results, err := parseSide(eqParts[1])
	if err != nil {
		return nil, err
	}
	if len(addends) == 0 {
		return nil, errors.New("invalid puzzle: expected at least one addend")
	}
	if len(results) != 1 {
		return nil, errors.New("invalid puzzle: expected exactly one result word")
	}
	words := append(addends, results[0])

	// Each letter contributes its digit times the sum of the place
	// values it occupies: positive in the addends, negative in the
	// result. A solution satisfies sum(coeff[l] * digit[l]) == 0.
	coeff := make(map[string]int)
	leading := make(map[string]bool)
	for i, w := range words {
		sign := 1
		if i == len(words)-1 {
			sign = -1
		}
		factor := 1
		for pos := len(w) - 1; pos >= 0; pos-- {
			coeff[string(w[pos])] += sign * factor
			factor *= 10
		}
		// The leading digit of a multi-digit number must not be zero.
		if len(w) > 1 {
			leading[string(w[0])] = true
		}
	}

	if len(coeff) > 10 {
		return nil, errors.New("no solution: more than ten distinct letters")
	}

	// Visit letters with the largest coefficient magnitude first so
	// the partial-sum bound prunes the search tree early.
	letters := make([]string, 0, len(coeff))
	for l := range coeff {
		letters = append(letters, l)
	}
	sort.Slice(letters, func(i, j int) bool {
		return abs(coeff[letters[i]]) > abs(coeff[letters[j]])
	})

	n := len(letters)
	// suffixMax[i] bounds the magnitude the letters i..n-1 can still
	// contribute to the equation.
	suffixMax := make([]int, n+1)
	for i := n - 1; i >= 0; i-- {
		suffixMax[i] = suffixMax[i+1] + abs(coeff[letters[i]])*9
	}

	assignment := make(map[string]int, n)
	used := make([]bool, 10)

	var search func(depth, sum int) bool
	search = func(depth, sum int) bool {
		if depth == n {
			return sum == 0
		}
		// The remaining letters cannot bring the sum back to zero.
		if sum > suffixMax[depth] || sum < -suffixMax[depth] {
			return false
		}
		l := letters[depth]
		c := coeff[l]
		if depth == n-1 && c != 0 {
			// The last letter's digit is determined by the equation.
			if sum%c != 0 {
				return false
			}
			d := -sum / c
			if d < 0 || d > 9 || used[d] || (leading[l] && d == 0) {
				return false
			}
			assignment[l] = d
			return true
		}
		zeroOK := !leading[l]
		for d := 0; d <= 9; d++ {
			if used[d] || (d == 0 && !zeroOK) {
				continue
			}
			used[d] = true
			assignment[l] = d
			if search(depth+1, sum+c*d) {
				return true
			}
			used[d] = false
		}
		return false
	}

	if !search(0, 0) {
		return nil, errors.New("no solution")
	}
	return assignment, nil
}

// parseSide splits one side of the puzzle into its words, skipping
// the '+' separators.
func parseSide(s string) ([]string, error) {
	var words []string
	for _, f := range strings.Fields(s) {
		if f == "+" {
			continue
		}
		if !isWord(f) {
			return nil, fmt.Errorf("invalid puzzle: %q is not a word", f)
		}
		words = append(words, f)
	}
	return words, nil
}

func isWord(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < 'A' || s[i] > 'Z' {
			return false
		}
	}
	return true
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

